import asyncio, os
from playwright.async_api import async_playwright
B = os.path.dirname(os.path.abspath(__file__)); SH = B + "/ptshots"
async def main():
    async with async_playwright() as p:
        b = await p.chromium.launch(); pg = await (await b.new_context(viewport={"width": 1480, "height": 1000})).new_page(); errs = []
        pg.on("pageerror", lambda e: errs.append("PAGEERR " + str(e)))
        await pg.goto("file://" + B + "/pti_mock.html"); await pg.wait_for_timeout(500)
        ev = lambda js: pg.evaluate(js)
        T = lambda: ev("(document.querySelector('.toast-fm')||{}).textContent||''")
        ST = lambda no: ev(f"__pt.stateOf(__pt.get('{no}'))")
        PS = lambda no: ev(f"__pt.get('{no}').ops.flatMap(o=>o.parts).map(p=>p.desc+':'+p.st+(p.bin?'@'+p.bin:'')).join(', ')")
        shot = lambda n: pg.locator(".wt-wrap").screenshot(path=f"{SH}/if_{n}.png")
        print("facts:", await ev("document.querySelector('.tg-facts').textContent"))
        await pg.click('[data-demo="d1"]'); await pg.keyboard.press("Escape"); await pg.click('.tg-next [data-a="do"]'); await pg.wait_for_timeout(80)
        print("1 pull:", await T(), "|", await ST("37688"), "| oh:", await ev("__pt.S().C.find(c=>c.pn==='85134770').oh"))
        await pg.click('[data-demo="d3"]'); await pg.click('.pt-sug [data-a="sgadd"] >> nth=0'); await pg.wait_for_timeout(50); print("3 add:", await T(), "|", await PS("37750"))
        await pg.click('.pt-sug [data-a="sgadd"]'); await pg.wait_for_timeout(50); print("3 card gone:", await ev("!document.querySelector('.pt-sug')"))
        await pg.click('[data-demo="d2"]'); await pg.click('[data-a="pullahead"]'); await pg.wait_for_timeout(50); print("2 pull ahead:", await T(), "|", await PS("37519"))
        await shot("pullahead")
        await pg.click('[data-demo="d4"]'); await pg.click('[data-a="ccsave"]'); await pg.wait_for_timeout(50); print("4 count:", await T(), "| fuel oh:", await ev("__pt.S().C.find(c=>c.pn==='21380475').oh"))
        await pg.click('[data-demo="d4"]'); await pg.fill('[data-cc="23223434"]','5'); print("4 live diff:", await ev("document.querySelector('[data-cc=\"23223434\"]').nextElementSibling.textContent"))
        await pg.click('[data-a="sosend"]'); await pg.wait_for_timeout(50); print("4 order:", await T())
        await pg.click('[data-demo="d5"]'); await pg.click('[data-a="scanpk"]'); await pg.wait_for_timeout(50); print("5 scan:", await T(), "|", await PS("37742"))
        await pg.click('[data-demo="d6"]'); await pg.wait_for_timeout(50)
        print("6 bins:", await ev("[...document.querySelectorAll('.pt-ln .r b')].map(x=>x.textContent).join(' | ')"))
        await pg.click('#pt-slip'); await pg.keyboard.press("Control+End"); await pg.keyboard.type("\n23137410  EGR VALVE  QTY 1"); await pg.wait_for_timeout(80)
        print("6 typed:", await ev("document.querySelector('.pt-slr b').textContent"), "| focus kept:", await ev("document.activeElement.id"))
        await pg.click('[data-a="kgo"]'); await pg.wait_for_timeout(80); print("6 checkin:", await T(), "| oil oh:", await ev("__pt.S().C.find(c=>c.pn==='21707133').oh"), "| ask:", await ev("__pt.U().ask.join(',')"))
        await shot("slip_done")
        await pg.click('[data-demo="d6"]'); await pg.click('[data-a="cmode"][data-v="scan"]'); await pg.wait_for_timeout(50); print("6 scan mode:", await ev("!!document.querySelector('#pt-scan')"))
        await pg.click('[data-demo="d8"]'); await pg.click('.pt-risk [data-a="rdo"] >> nth=0'); await pg.wait_for_timeout(50); print("8 risk → pop:", await ev("(document.querySelector('.tg-pop .tg-ph b')||{}).textContent"))
        await pg.click('[data-demo="d9"]'); h = await pg.query_selector('.pt-cols .c >> nth=3'); bb = await h.bounding_box(); await pg.mouse.move(bb["x"]+10, bb["y"]+60); await pg.wait_for_timeout(80)
        print("9 tip:", await ev("document.querySelector('.tk-tip').hidden?'hidden':document.querySelector('.tk-tip').textContent"))
        await pg.click('[data-demo="d7"]'); h = await pg.query_selector('.pt-scr >> nth=2'); bb = await h.bounding_box(); await pg.mouse.move(bb["x"]+200, bb["y"]+15); await pg.wait_for_timeout(80)
        print("7 tip:", await ev("document.querySelector('.tk-tip').hidden?'hidden':document.querySelector('.tk-tip').textContent"))
        await pg.click('[data-demo="d1"]'); await pg.click('.tk-note [data-a="notex"]'); print("note closed:", await ev("document.querySelector('.tk-note').hidden"))
        print(errs or "no errors"); await b.close()
asyncio.run(main())
